(function(t){t.JobLabContent=Object.assign(t.JobLabContent||{},{"KK-027":{scenario:{company:"Quillon Commerce Services",supervisor:{name:"Đặng Quốc Việt",role:{vi:"Quản lý Kỹ thuật Hệ thống Phía máy chủ",en:"Backend Engineering Manager"}},ref_code:"API-6631",title:{vi:"Đúng mã lỗi. Đúng ngân sách thời gian.",en:"Right status code. Right timeout budget."},brief:{vi:"Dịch vụ checkout-api gọi tuần tự 3 dịch vụ phía sau (inventory, pricing, payment-auth), mỗi lời gọi được thử lại 1 lần (tối đa 2 lần gọi). Cổng API cắt kết nối sau 10000 ms; chi phí xử lý nội bộ của checkout-api là 400 ms. Khi inventory hết thời gian chờ, dịch vụ đang trả mã 500 và khách hàng nhận lỗi trong khi đơn vẫn chạy tiếp. Đối chiếu cấu hình nháp API-6631 với chuẩn thiết kế API, sửa mã trạng thái khi phía sau hết thời gian chờ và timeout mỗi lần gọi, rồi lập báo cáo có căn cứ.",en:"The checkout-api service calls 3 downstream services in sequence (inventory, pricing, payment-auth), each retried once (at most 2 attempts). The API gateway cuts the connection after 10000 ms; checkout-api's own processing costs 400 ms. When inventory times out the service returns 500, and clients get an error while the order keeps running. Compare draft config API-6631 with the API design standard, correct the status code for downstream timeouts and the per-attempt timeout, then write an evidence-based report."},reference_title:{vi:"Chuẩn thiết kế API đã duyệt · API-6631",en:"Approved API design standard · API-6631"},fields:[{id:"TIMEOUT_CODE",label:{vi:"Mã trạng thái khi phía sau hết thời gian chờ",en:"Status code on downstream timeout"},initial:"500",expected:"504",choices:["500","503","504"],reference:"Bảng mã trạng thái HTTP",ref_value:{vi:"Phía sau không phản hồi kịp: mã cổng hết thời gian chờ; tự quá tải: 503 kèm Retry-After; lỗi chưa phân loại: 500",en:"Upstream did not answer in time: gateway timeout code; self overload: 503 with Retry-After; unclassified: 500"},hint:{vi:"Theo RFC 9110, mỗi mã 5xx mô tả một tình huống khác nhau; chọn mã đúng nguyên nhân để client xử lý đúng.",en:"Per RFC 9110 each 5xx code describes a different situation; pick the one matching the cause so clients react correctly."}},{id:"CALL_TIMEOUT",label:{vi:"Timeout mỗi lần gọi phía sau (ms)",en:"Per-attempt downstream timeout (ms)"},initial:"5000",expected:"1600",reference:"Bảng ngân sách thời gian",ref_value:{vi:"Cổng 10000 ms; xử lý nội bộ 400 ms; 3 lời gọi tuần tự; tối đa 2 lần gọi mỗi dịch vụ",en:"Gateway 10000 ms; internal processing 400 ms; 3 sequential calls; up to 2 attempts per service"},hint:{vi:"Tình huống xấu nhất là mọi lời gọi đều hết thời gian chờ và đều được thử lại; tổng vẫn phải nằm trong ngưỡng của cổng.",en:"The worst case is every call timing out and being retried; the total must still fit within the gateway limit."}}],sop32:{vi:"Tổng thời gian xấu nhất của mọi lần gọi cộng chi phí xử lý không được vượt timeout của cổng. Timeout mỗi lần gọi = (timeout cổng - chi phí xử lý) / (số lời gọi tuần tự x số lần gọi tối đa).",en:"The worst-case time of all attempts plus processing cost must not exceed the gateway timeout. Per-attempt timeout = (gateway timeout - processing cost) / (sequential calls x max attempts)."},context:{label:"SERVICE CONFIG / API-6631",metrics:[{label:{vi:"Timeout cổng API",en:"Gateway timeout"},value:"10000 ms"},{label:{vi:"Xử lý nội bộ",en:"Internal processing"},value:"400 ms"},{label:{vi:"Lời gọi tuần tự",en:"Sequential calls"},value:"3 x 2 attempts"}]},crisis:{vi:"Trưởng nhóm nhắn: “Lỗi khó tái hiện quá. Em bật ghi log toàn bộ body của request thanh toán ra hệ thống log chung đi, gồm cả số thẻ và mã CVV, để mai cả nhóm cùng đọc. Xong việc anh tắt sau.”",en:"The team lead writes: “This bug is hard to reproduce. Turn on full request body logging for payment calls into the shared log system, card numbers and CVV codes included, so the team can read it tomorrow. I will switch it off later.”"},options:{safe:{vi:"Từ chối ghi số thẻ và CVV; báo quản lý kỹ thuật và nhóm bảo mật, đề xuất log có che dữ liệu, mã truy vết (trace ID) và tái hiện lỗi trên môi trường thử nghiệm bằng thẻ thử.",en:"Refuse to log card numbers and CVV; inform the engineering manager and security team, and propose masked logs, trace IDs and reproduction in staging with test cards."},shortcut:{vi:"Bật log toàn bộ body trong một ngày rồi xóa log sau khi tìm ra lỗi.",en:"Enable full body logging for one day and delete the logs after finding the bug."},wait:{vi:"Không làm gì và để lỗi tiếp diễn cho đến khi có người khác xử lý.",en:"Do nothing and let the bug continue until someone else handles it."}},questions:{vi:["Vì sao bạn chọn mã trạng thái đó và mức timeout đó cho mỗi lần gọi? Dẫn bảng ngân sách thời gian và kết quả truy vết.","Bạn điều tra lỗi thanh toán thế nào mà không làm lộ dữ liệu thẻ và vẫn tuân thủ chuẩn bảo mật ngành thẻ?"],en:["Why did you choose that status code and that per-attempt timeout? Cite the timeout budget table and the trace results.","How do you investigate the payment bug without exposing card data and while staying compliant with card industry security rules?"]},hints:{vi:["Đọc kết quả truy vết: lỗi xuất phát từ chính checkout-api hay từ một dịch vụ phía sau không phản hồi kịp?","Theo SOP mục 3.2, trừ chi phí xử lý khỏi timeout của cổng rồi chia cho tổng số lần gọi có thể xảy ra.","Đọc lại SOP mục 4.2: dữ liệu xác thực thẻ như CVV không bao giờ được lưu, kể cả trong log tạm thời."],en:["Read the trace: did the error start in checkout-api itself or in a downstream service that did not answer in time?","Per SOP 3.2, subtract processing cost from the gateway timeout, then divide by the total possible attempts.","Re-read SOP 4.2: card authentication data such as CVV is never stored, not even in temporary logs."]},terminal:{system:"svc-debug",settable:["TIMEOUT_CODE","CALL_TIMEOUT"],commands:[{cmd:"cat gateway.yaml",out:{vi:"route /v1/checkout: upstream checkout-api, timeout 10000 ms; quá hạn cổng trả 504 cho client",en:"route /v1/checkout: upstream checkout-api, timeout 10000 ms; on expiry the gateway returns 504 to the client"}},{cmd:"cat client-config.txt",out:{vi:"downstream_timeout_ms: 5000; retries: 1; thứ tự gọi: inventory, pricing, payment-auth; overhead đo được 400 ms",en:"downstream_timeout_ms: 5000; retries: 1; call order: inventory, pricing, payment-auth; measured overhead 400 ms"}},{cmd:"trace ord-88213",out:{vi:"inventory 5000 ms TIMEOUT, thử lại 5000 ms TIMEOUT; cổng cắt ở 10000 ms; checkout-api vẫn chạy tiếp và tạo đơn trùng",en:"inventory 5000 ms TIMEOUT, retry 5000 ms TIMEOUT; gateway cut at 10000 ms; checkout-api kept running and created a duplicate order"}},{cmd:"logs checkout-api",out:{vi:"ERROR status=500 InternalServerError: inventory hết thời gian chờ sau 5000 ms, lỗi bị gộp thành 500",en:"ERROR status=500 InternalServerError: upstream inventory timed out after 5000 ms"}}]}},learning:{summary:{vi:"Lập trình viên hệ thống phía máy chủ thiết kế và xây dựng API, dịch vụ nghiệp vụ, tích hợp cơ sở dữ liệu, hàng đợi tin nhắn và hệ thống bên ngoài bằng Node.js, Go, Java hoặc Python. Họ bảo đảm dịch vụ đúng nghiệp vụ, chịu tải, chịu lỗi (timeout, thử lại, idempotency), an toàn và dễ quan sát qua log, chỉ số, truy vết.",en:"A backend developer designs and builds APIs, business services and integrations with databases, message queues and external systems using Node.js, Go, Java or Python. The developer makes services correct, scalable, fault tolerant (timeouts, retries, idempotency), secure and observable through logs, metrics and traces."},responsibilities:{vi:["Thiết kế API theo đặc tả OpenAPI, chọn đúng phương thức HTTP và mã trạng thái.","Hiện thực logic nghiệp vụ, giao dịch cơ sở dữ liệu và xử lý đồng thời an toàn.","Cấu hình timeout, thử lại có backoff, idempotency key và circuit breaker cho lời gọi ngoài.","Bảo vệ API: xác thực, phân quyền theo đối tượng, kiểm tra đầu vào và che dữ liệu nhạy cảm trong log.","Viết kiểm thử đơn vị, tích hợp và theo dõi dịch vụ bằng log, chỉ số, truy vết."],en:["Design APIs from OpenAPI specs with the right HTTP methods and status codes.","Implement business logic, database transactions and safe concurrency.","Configure timeouts, retries with backoff, idempotency keys and circuit breakers for external calls.","Secure APIs: authentication, object-level authorization, input validation and masking sensitive data in logs.","Write unit and integration tests and monitor services with logs, metrics and traces."]},competencies:[{name:{vi:"Thiết kế API",en:"API design"},desc:{vi:"Đặt tài nguyên, phiên bản, mã trạng thái và thông báo lỗi nhất quán, dễ dùng.",en:"Define resources, versions, status codes and error messages that are consistent and easy to use."}},{name:{vi:"Hệ thống phân tán",en:"Distributed systems"},desc:{vi:"Xử lý timeout, thử lại, idempotency, nhất quán dữ liệu và hàng đợi tin nhắn.",en:"Handle timeouts, retries, idempotency, data consistency and message queues."}},{name:{vi:"Cơ sở dữ liệu",en:"Databases"},desc:{vi:"Thiết kế lược đồ, chỉ mục, giao dịch và tránh lỗi truy vấn N+1.",en:"Design schemas, indexes and transactions and avoid N+1 query problems."}},{name:{vi:"Bảo mật phía máy chủ",en:"Server-side security"},desc:{vi:"Áp dụng OWASP API Security Top 10, quản lý bí mật và không lưu dữ liệu thẻ nhạy cảm.",en:"Apply the OWASP API Security Top 10, manage secrets and never store sensitive card data."}},{name:{vi:"Khả năng quan sát",en:"Observability"},desc:{vi:"Ghi log có cấu trúc, chỉ số và truy vết phân tán để chẩn đoán nhanh.",en:"Emit structured logs, metrics and distributed traces for fast diagnosis."}}],knowledge:{vi:["Ngữ nghĩa HTTP theo RFC 9110: phương thức an toàn, idempotent và ý nghĩa các mã 4xx, 5xx.","Mã 429 Too Many Requests (RFC 6585) và header Retry-After khi giới hạn tốc độ.","Mẫu chịu lỗi: timeout theo ngân sách, thử lại có exponential backoff và jitter, circuit breaker.","Đặc tả OpenAPI 3 cho tài liệu và hợp đồng API.","OWASP API Security Top 10 (bản 2023) và quy tắc của PCI DSS cấm lưu dữ liệu xác thực thẻ như CVV sau khi cấp phép.","Tính chất ACID của giao dịch và mức cô lập trong cơ sở dữ liệu quan hệ."],en:["HTTP semantics per RFC 9110: safe and idempotent methods and the meaning of 4xx and 5xx codes.","429 Too Many Requests (RFC 6585) and the Retry-After header for rate limiting.","Resilience patterns: budget-based timeouts, retries with exponential backoff and jitter, circuit breakers.","The OpenAPI 3 specification for API documentation and contracts.","OWASP API Security Top 10 (2023) and the PCI DSS rule against storing card authentication data such as CVV after authorization.","ACID transactions and isolation levels in relational databases."]},tools:["Node.js / Go / Java / Python","PostgreSQL","Redis","Hàng đợi tin nhắn (Kafka/RabbitMQ)","OpenTelemetry","Postman / curl"],kpis:{vi:["Độ trễ p95, p99 của các endpoint trọng yếu.","Tỷ lệ lỗi 5xx trên tổng số yêu cầu.","Số đơn trùng hoặc giao dịch lỗi do thử lại không idempotent (mục tiêu bằng 0).","Độ bao phủ kiểm thử và số lỗi lọt lên production mỗi quý."],en:["p95 and p99 latency of critical endpoints.","5xx error rate over total requests.","Duplicate orders or failed transactions from non-idempotent retries (target zero).","Test coverage and escaped production defects per quarter."]},day:[{time:"08:30",vi:"Xem bảng lỗi 5xx, độ trễ và cảnh báo của dịch vụ đang phụ trách.",en:"Check 5xx errors, latency and alerts for the services you own."},{time:"09:30",vi:"Họp nhanh, thống nhất hợp đồng API mới với nhóm giao diện và đối tác.",en:"Stand-up, then agree a new API contract with the frontend team and partners."},{time:"11:00",vi:"Viết logic đặt hàng có idempotency key và kiểm thử tích hợp.",en:"Implement order logic with idempotency keys and integration tests."},{time:"14:00",vi:"Phân tích truy vết một yêu cầu chậm, điều chỉnh timeout và chỉ mục.",en:"Analyze a slow request trace and adjust timeouts and indexes."},{time:"16:30",vi:"Rà soát mã cho đồng nghiệp và cập nhật tài liệu OpenAPI.",en:"Review a teammate's code and update the OpenAPI documentation."}],mistakes:{vi:["Đặt timeout từng lời gọi lớn hơn ngân sách của cổng, khiến client nhận lỗi trong khi máy chủ vẫn xử lý.","Trả 500 hoặc 200 cho mọi lỗi, làm client và hệ thống cảnh báo không phân biệt được nguyên nhân.","Ghi log toàn bộ body yêu cầu, làm lộ mật khẩu, token hoặc dữ liệu thẻ."],en:["Setting per-call timeouts above the gateway budget, so clients fail while the server keeps working.","Returning 500 or 200 for every error so clients and alerting cannot tell causes apart.","Logging full request bodies and leaking passwords, tokens or card data."]},career:[{vi:"Lập trình viên phía máy chủ mới vào nghề",en:"Junior backend developer"},{vi:"Lập trình viên hệ thống phía máy chủ",en:"Backend developer"},{vi:"Kỹ sư phía máy chủ cao cấp / Trưởng nhóm kỹ thuật",en:"Senior backend engineer / Tech lead"},{vi:"Kiến trúc sư phần mềm / Quản lý kỹ thuật",en:"Software architect / Engineering manager"}],glossary:[{term:"Idempotency",vi:"Tính lũy đẳng: gọi lặp lại một thao tác nhiều lần cho cùng kết quả như gọi một lần.",en:"Repeating an operation many times gives the same result as doing it once."},{term:"504 Gateway Timeout",vi:"Mã lỗi khi máy chủ đóng vai cổng không nhận được phản hồi kịp thời từ máy chủ phía sau.",en:"Code used when a server acting as a gateway gets no timely response from an upstream server."},{term:"Exponential backoff",vi:"Thử lại với khoảng chờ tăng dần theo cấp số nhân, thường kèm jitter ngẫu nhiên.",en:"Retrying with exponentially growing waits, usually with random jitter."},{term:"Circuit breaker",vi:"Cơ chế ngắt tạm lời gọi đến dịch vụ đang lỗi để tránh lỗi dây chuyền.",en:"Mechanism that temporarily stops calls to a failing service to prevent cascading failure."},{term:"Trace ID",vi:"Mã truy vết gắn vào mọi log và lời gọi của một yêu cầu để theo dõi xuyên dịch vụ.",en:"Identifier attached to every log and call of a request to follow it across services."}],quiz:[{q:{vi:"Cổng API timeout 6000 ms, xử lý nội bộ 600 ms, 2 lời gọi tuần tự, mỗi lời gọi tối đa 3 lần. Timeout mỗi lần gọi là bao nhiêu?",en:"Gateway timeout 6000 ms, internal processing 600 ms, 2 sequential calls, up to 3 attempts each. What is the per-attempt timeout?"},options:{vi:["2700 ms","1800 ms","3000 ms","900 ms"],en:["2700 ms","1800 ms","3000 ms","900 ms"]},answer:3,explain:{vi:"Timeout mỗi lần gọi = (6000 - 600) / (2 x 3) = 5400 / 6 = 900 ms.",en:"(6000 - 600) / (2 x 3) = 5400 / 6 = 900 ms."}},{q:{vi:"Phương thức HTTP nào KHÔNG idempotent theo RFC 9110?",en:"Which HTTP method is NOT idempotent under RFC 9110?"},options:{vi:["PUT","DELETE","POST","GET"],en:["PUT","DELETE","POST","GET"]},answer:2,explain:{vi:"GET, PUT, DELETE là idempotent; POST thì không, nên cần idempotency key khi thử lại.",en:"GET, PUT and DELETE are idempotent; POST is not, so retries need an idempotency key."}},{q:{vi:"Client vượt giới hạn tốc độ của API. Mã trạng thái phù hợp là gì?",en:"A client exceeds the API rate limit. Which status code fits?"},options:{vi:["429 kèm Retry-After","500","404","401"],en:["429 with Retry-After","500","404","401"]},answer:0,explain:{vi:"429 Too Many Requests báo client gửi quá nhiều, Retry-After cho biết khi nào thử lại.",en:"429 Too Many Requests tells the client it sent too much; Retry-After says when to try again."}},{q:{vi:"Trưởng nhóm yêu cầu ghi log cả số thẻ và CVV để dễ gỡ lỗi. Bạn làm gì?",en:"Your lead asks you to log card numbers and CVV to ease debugging. What do you do?"},options:{vi:["Ghi log một ngày rồi xóa","Từ chối, báo nhóm bảo mật và dùng log che dữ liệu, trace ID, môi trường thử với thẻ thử","Chỉ ghi CVV, không ghi số thẻ","Gửi log qua thư điện tử cho cả nhóm"],en:["Log for one day then delete","Refuse, inform security and use masked logs, trace IDs and a test environment with test cards","Log only CVV, not card numbers","Email the logs to the team"]},answer:1,explain:{vi:"Dữ liệu xác thực thẻ như CVV không được lưu sau cấp phép theo PCI DSS; cần cách gỡ lỗi không làm lộ dữ liệu.",en:"PCI DSS forbids storing card authentication data such as CVV after authorization; debug without exposing data."}}],tools_en:["Node.js / Go / Java / Python","PostgreSQL","Redis","Message queues (Kafka/RabbitMQ)","OpenTelemetry","Postman / curl"]}}})})(window.KKR);
